-- Generated by app/scripts/document_analytical_foundation.py from the metric registry.
-- Local SQLite only. Bind ? parameters in their declared order.
-- Requires analytical connection UDFs including AUDIT_QUALIFIED / AUDIT_LINEAGE.
-- Review/internal validation only: public consumers use Analytics.query for disclosure control.

-- metric_id: ub.complete_module_coverage
-- bindings: [1, 1, 1, 1]
SELECT COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND (e."has_assignment_ub"=? AND e."has_ub_a"=? AND e."has_ub_b"=? AND e."has_ub_c"=?) THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "assignment_id","status_keberadaan","kbli_akhir","kategori_kbli","has_assignment_ub","has_ub_a","has_ub_b","has_ub_c" FROM "mart_ub_integrated" LIMIT -1 OFFSET 0) e WHERE 1=1;
